{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.plus_catalog_allocation_hygiene AS WITH inward_by_date AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, MAX(CATEGORY) AS CATEGORY, INWARD_DATE, SUM(QTY) AS QTY, MIN(INWARD_DATE) OVER ( PARTITION BY UPPER(TRIM(SKU_GROUP)) ) AS FIRST_INWARD_DATE FROM snitch_db.maplemonk.plus_inwards_master_2 WHERE INWARD_TYPE = \'ACTUAL_INWARD\' GROUP BY UPPER(TRIM(SKU_GROUP)), CATEGORY, INWARD_DATE ), actual_inwards AS ( SELECT SKU_GROUP, CATEGORY, FIRST_INWARD_DATE, INWARD_DATE AS LAST_INWARD_DATE, QTY AS TOTAL_INWARDED_QTY FROM inward_by_date QUALIFY ROW_NUMBER() OVER ( PARTITION BY SKU_GROUP ORDER BY INWARD_DATE DESC ) = 1 ), catalog AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, LIVE_DATE, STATUS, FINAL_STATUS, SHOPIFY_ACTUAL_INV, UNITS_ON_HAND, CREATED_AT_DATE, CATALOGIX_SENT_TIMESTAMP, CATALOGIX_RECEIVED_TIMESTAMP FROM snitch_db.maplemonk.sku_group_sample_to_live QUALIFY ROW_NUMBER() OVER ( PARTITION BY UPPER(TRIM(SKU_GROUP)) ORDER BY LAST_UPDATED_AT_ACTUAL DESC NULLS LAST, LAST_UPDATED_AT DESC NULLS LAST ) = 1 ), inventory_snapshots AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, CATEGORY, CAST(SNAPSHOT_TS AS DATE) AS SNAPSHOT_DATE, CUT_SIZE, OFFLINE_INVENTORY AS STORE_INVENTORY, ONLINE_INVENTORY, ROW_NUMBER() OVER ( PARTITION BY UPPER(TRIM(SKU_GROUP)), CAST(SNAPSHOT_TS AS DATE) ORDER BY SNAPSHOT_TS DESC ) AS RN FROM snitch_db.maplemonk.inventory_daily_snapshot_latest WHERE UPPER(TRIM(SKU_GROUP)) LIKE \'4MBG%\' OR UPPER(TRIM(SKU_GROUP)) LIKE \'4B%\' ), latest_daily_inventory AS ( SELECT SKU_GROUP, CATEGORY, SNAPSHOT_DATE, CUT_SIZE, STORE_INVENTORY, ONLINE_INVENTORY FROM inventory_snapshots WHERE RN = 1 ), warehouse_inventory AS ( SELECT UPPER(TRIM(\"Item SkuCode\")) AS SKU_GROUP, SUM(COALESCE(INVENTORY, 0)) AS WAREHOUSE_INVENTORY FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE UPPER(TRIM(\"Item SkuCode\")) LIKE \'4MBG%\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'4B%\' GROUP BY UPPER(TRIM(\"Item SkuCode\")) ), final_data AS ( SELECT inv.SNAPSHOT_DATE, inv.SKU_GROUP, inv.CATEGORY, inv.CUT_SIZE, inv.STORE_INVENTORY, inv.ONLINE_INVENTORY, CASE WHEN LOWER(TRIM(inv.CUT_SIZE)) = \'cut\' THEN inv.STORE_INVENTORY ELSE 0 END AS CUT_SIZE_INVENTORY_QTY, CASE WHEN LOWER(TRIM(inv.CUT_SIZE)) = \'non_cut\' THEN inv.STORE_INVENTORY ELSE 0 END AS FULL_SIZE_INVENTORY_QTY, i.FIRST_INWARD_DATE, i.LAST_INWARD_DATE, i.TOTAL_INWARDED_QTY, c.CREATED_AT_DATE, c.LIVE_DATE, c.STATUS AS CATALOG_STATUS, c.FINAL_STATUS, c.CATALOGIX_SENT_TIMESTAMP, c.CATALOGIX_RECEIVED_TIMESTAMP, c.SHOPIFY_ACTUAL_INV, c.UNITS_ON_HAND, wi.WAREHOUSE_INVENTORY, CASE WHEN c.SKU_GROUP IS NULL THEN \'INWARDED_NOT_CATALOGUED\' WHEN LOWER(COALESCE(c.STATUS, \'\')) LIKE \'%cancel%\' THEN \'CANCELLED\' WHEN c.LIVE_DATE IS NULL AND LOWER(COALESCE(c.STATUS, \'\')) LIKE \'%draft%\' THEN \'INWARDED_IN_DRAFT\' WHEN wi.WAREHOUSE_INVENTORY > 0 AND COALESCE(inv.STORE_INVENTORY, 0) = 0 THEN \'INWARDED_NOT_ALLOCATED\' ELSE \'OK\' END AS HYGIENE_STATUS, CASE WHEN c.SKU_GROUP IS NULL THEN 1 ELSE 0 END AS NOT_CATALOGUED_FLAG, CASE WHEN c.SKU_GROUP IS NOT NULL AND LOWER(COALESCE(c.STATUS, \'\')) LIKE \'%cancel%\' THEN 1 ELSE 0 END AS CANCELLED_FLAG, CASE WHEN c.SKU_GROUP IS NOT NULL AND c.LIVE_DATE IS NULL AND LOWER(COALESCE(c.STATUS, \'\')) LIKE \'%draft%\' THEN 1 ELSE 0 END AS IN_DRAFT_FLAG, CASE WHEN wi.WAREHOUSE_INVENTORY > 0 AND COALESCE(inv.STORE_INVENTORY, 0) = 0 THEN 1 ELSE 0 END AS NOT_ALLOCATED_FLAG FROM latest_daily_inventory inv LEFT JOIN actual_inwards i ON inv.SKU_GROUP = i.SKU_GROUP LEFT JOIN catalog c ON inv.SKU_GROUP = c.SKU_GROUP LEFT JOIN warehouse_inventory wi ON inv.SKU_GROUP = wi.SKU_GROUP ) SELECT * FROM final_data;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            